"use client";

import { useCallback, useEffect, useState } from "react";

type AppKey = "customer" | "vendor" | "partner" | "admin";
type Service = "Food" | "Grocery" | "Vegetables" | "Mart" | "Bike Taxi" | "Parcel";
type Product = { id:string; service:Service; vendor:string; name:string; description:string; price:number; stock:number; rating:number; eta:string };
type Order = { id:string; reference:string; service:Service; vendor:string; vendor_id:string; customer:string; customer_id:string; partner:string|null; partner_id:string|null; status:string; total:number; details:Record<string,unknown>; created_at:string; updated_at:string };
type Offer = { id:string;vendor_id:string;vendor:string;title:string;code:string;discount_percent:number;min_order:number;active:number;created_at:string;updated_at:string };
type PlatformUser = { id:string;email:string;name:string;role:string;status:string;created_at?:string };
type Snapshot = { actor:PlatformUser; products:Product[]; orders:Order[]; offers:Offer[]; services:{service:Service;enabled:number}[]; pricing:{service:Service;base_fare:number;per_km:number;platform_fee:number}[]; settings:Record<string,string>; users:PlatformUser[]; auditLogs:Record<string,unknown>[] };
type ApiResult = { success:boolean; data?:Snapshot; error?:{code?:string;message:string}; message?:string|null };
type ErrorState = { code:string; message:string };

const serviceMeta:{name:Service;letter:string;note:string}[] = [
  {name:"Food",letter:"F",note:"25–35 min"},{name:"Grocery",letter:"G",note:"30–45 min"},
  {name:"Vegetables",letter:"V",note:"Farm fresh"},{name:"Mart",letter:"M",note:"10–20 min"},
  {name:"Bike Taxi",letter:"B",note:"From ₹29"},{name:"Parcel",letter:"P",note:"Send local"},
];
const nav:Record<AppKey,string[]> = {
  customer:["Home","Search","Activity","Cart","Account"],
  vendor:["Dashboard","Orders","Products / Menu","Inventory","Offers","Payments","Store","Profile"],
  partner:["Home","Requests","Current Task","Trips","Earnings","Support","Profile"],
  admin:["Dashboard","Live Operations","Orders","Rides","Parcels","Vendors","Delivery Partners","Customers","Catalog","Finance","Support","Reports","Settings"],
};
const commerce:Service[] = ["Food","Grocery","Vegetables","Mart"];
const money = (value:number) => `₹${Math.round(value).toLocaleString("en-IN")}`;
const label = (value:string) => value.replaceAll("_"," ").toLowerCase().replace(/\b\w/g,(x)=>x.toUpperCase());
const terminalStatuses=["DELIVERED","COMPLETED","CANCELLED_BY_ADMIN","VENDOR_REJECTED"];

function detail(order:Order,key:string,fallback="—"){const value=order.details[key];return typeof value==="string"||typeof value==="number"?String(value):fallback;}
function orderSummary(order:Order){const items=Array.isArray(order.details.items)?order.details.items as {name?:string;qty?:number}[]:[];if(items.length)return items.map((x)=>`${x.qty||1}× ${x.name||"Item"}`).join(", ");return order.service==="Parcel"?detail(order,"packageType","Parcel"): `${detail(order,"distance","4.2")} km trip`;}

function Brand(){ return <div className="brand"><b>g</b><span>goocart</span></div>; }
function Status({value}:{value:string}){ return <span className={`status status-${value.toLowerCase()}`}>● {label(value)}</span>; }
function Empty({title,copy}:{title:string;copy:string}){ return <div className="empty-state"><i>g</i><h3>{title}</h3><p>{copy}</p></div>; }

function useGoocart(){
  const [state,setState] = useState<Snapshot|null>(null); const [busy,setBusy] = useState(false); const [toast,setToast] = useState(""); const [error,setError] = useState<ErrorState|null>(null);
  const load = useCallback(async(silent=false)=>{ try{ if(!silent)setBusy(true); const res=await fetch("/api/goocart",{cache:"no-store"}); const json=await res.json() as ApiResult; if(!json.success||!json.data){setError({code:json.error?.code||"UNKNOWN",message:json.error?.message||"Unable to load Goocart"});return;} setState(json.data);setError(null); }catch(e){setError({code:"NETWORK_ERROR",message:e instanceof Error?e.message:"Unable to load Goocart"});}finally{if(!silent)setBusy(false);}},[]);
  useEffect(()=>{const initial=setTimeout(()=>void load(),0);const timer=setInterval(()=>void load(true),5000);return()=>{clearTimeout(initial);clearInterval(timer);};},[load]);
  const act=useCallback(async(body:Record<string,unknown>)=>{try{setBusy(true);const res=await fetch("/api/goocart",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const json=await res.json() as ApiResult;if(!json.success||!json.data)throw new Error(json.error?.message||"Action failed");setState(json.data);setToast(json.message||"Updated");setTimeout(()=>setToast(""),2800);return true;}catch(e){setToast(e instanceof Error?e.message:"Action failed");setTimeout(()=>setToast(""),3500);return false;}finally{setBusy(false);}},[]);
  return {state,busy,toast,error,act,retry:load};
}

async function logout(){await fetch("/api/auth/logout",{method:"POST"});window.location.reload();}

type AuthMode = "password" | "otp";
function AuthGate({onAuthenticated}:{onAuthenticated:()=>void}){
  const [mode,setMode]=useState<AuthMode>("password"); const [isSignup,setIsSignup]=useState(false); const [step,setStep]=useState<"form"|"code">("form");
  const [name,setName]=useState(""); const [email,setEmail]=useState(""); const [password,setPassword]=useState(""); const [identifier,setIdentifier]=useState(""); const [code,setCode]=useState("");
  const [busy,setBusy]=useState(false); const [error,setError]=useState("");
  const switchMode=(next:AuthMode)=>{setMode(next);setStep("form");setError("");};

  const submitPassword=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");
    try{const res=await fetch(isSignup?"/api/auth/signup":"/api/auth/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(isSignup?{email,password,name}:{email,password})});const json=await res.json() as ApiResult;if(!json.success)throw new Error(json.error?.message||"Something went wrong");onAuthenticated();}
    catch(e){setError(e instanceof Error?e.message:"Something went wrong");}finally{setBusy(false);}};

  const requestCode=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");
    try{const res=await fetch("/api/auth/otp/request",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({identifier,purpose:isSignup?"SIGNUP":"LOGIN"})});const json=await res.json() as ApiResult;if(!json.success)throw new Error(json.error?.message||"Could not send code");setStep("code");}
    catch(e){setError(e instanceof Error?e.message:"Could not send code");}finally{setBusy(false);}};

  const verifyCode=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError("");
    try{const res=await fetch("/api/auth/otp/verify",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({identifier,code,name,purpose:isSignup?"SIGNUP":"LOGIN"})});const json=await res.json() as ApiResult;if(!json.success)throw new Error(json.error?.message||"That code is incorrect or has expired");onAuthenticated();}
    catch(e){setError(e instanceof Error?e.message:"That code is incorrect or has expired");}finally{setBusy(false);}};

  return <main className="auth-gate">
    <Brand/>
    <h1>{isSignup?"Create your account":"Sign in to Goocart"}</h1>
    <p className="auth-subtitle">One secure sign-in for customers, vendors and delivery partners. Your approved workspace opens automatically.</p>
    <div className="auth-tabs"><button className={mode==="password"?"active":""} onClick={()=>switchMode("password")}>Email &amp; password</button><button className={mode==="otp"?"active":""} onClick={()=>switchMode("otp")}>Email or phone code</button></div>
    {mode==="password"&&<form className="auth-form" onSubmit={(e)=>void submitPassword(e)}>
      {isSignup&&<label>Full name<input required minLength={2} value={name} onChange={(e)=>setName(e.target.value)}/></label>}
      <label>Email<input required type="email" value={email} onChange={(e)=>setEmail(e.target.value)}/></label>
      <label>Password<input required minLength={8} type="password" value={password} onChange={(e)=>setPassword(e.target.value)}/></label>
      {error&&<p className="auth-error">{error}</p>}
      <button className="primary" disabled={busy}>{busy?"Please wait...":isSignup?"Create account":"Sign in"}</button>
    </form>}
    {mode==="otp"&&step==="form"&&<form className="auth-form" onSubmit={(e)=>void requestCode(e)}>
      {isSignup&&<label>Full name<input required minLength={2} value={name} onChange={(e)=>setName(e.target.value)}/></label>}
      <label>Email or phone<input required value={identifier} onChange={(e)=>setIdentifier(e.target.value)}/></label>
      {error&&<p className="auth-error">{error}</p>}
      <button className="primary" disabled={busy}>{busy?"Sending...":"Send code"}</button>
    </form>}
    {mode==="otp"&&step==="code"&&<form className="auth-form" onSubmit={(e)=>void verifyCode(e)}>
      <p>Enter the 6-digit code sent to {identifier}.</p>
      <label>Code<input required pattern="[0-9]{6}" inputMode="numeric" value={code} onChange={(e)=>setCode(e.target.value)}/></label>
      {error&&<p className="auth-error">{error}</p>}
      <button className="primary" disabled={busy}>{busy?"Verifying...":"Verify & continue"}</button>
      <button type="button" className="auth-switch" onClick={()=>setStep("form")}>Use a different email or phone</button>
    </form>}
    <button className="auth-switch" onClick={()=>{setIsSignup(!isSignup);setError("");}}>{isSignup?"Already have an account? Sign in":"New to Goocart? Create an account"}</button>
  </main>;
}

function Customer({state,act,busy}:{state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){
  const [service,setService]=useState<Service>("Food"); const [tab,setTab]=useState("Home"); const [query,setQuery]=useState(""); const [cart,setCart]=useState<Record<string,number>>({});
  const products=state.products.filter((x)=>x.service===service); const cartItems=Object.entries(cart).map(([id,qty])=>({product:state.products.find((x)=>x.id===id)!,qty})).filter((x)=>x.product);
  const cartTotal=cartItems.reduce((sum,x)=>sum+x.product.price*x.qty,0); const activeOrders=state.orders;
  const enabled=(name:Service)=>Boolean(state.services.find((x)=>x.service===name)?.enabled);
  const add=(product:Product)=>{const existing=cartItems[0]?.product;if(existing&&existing.vendor!==product.vendor){setCart({[product.id]:1});}else setCart((old)=>({...old,[product.id]:Math.min(product.stock,(old[product.id]||0)+1)}));};
  const updateQty=(id:string,amount:number)=>setCart((old)=>{const next={...old};next[id]=(next[id]||0)+amount;if(next[id]<=0)delete next[id];return next;});
  const checkout=async()=>{const ok=await act({action:"order.create",items:cartItems.map((x)=>({productId:x.product.id,qty:x.qty}))});if(ok){setCart({});setTab("Activity");}};
  return <div className="customer"><header><div className="location"><i>●</i><span><small>DELIVERING TO</small><b>Home⌄</b><em>Jangareddigudem</em></span></div><Brand/><div className="head-actions"><button aria-label="Notifications">◎</button><button>BR</button></div></header>
    <main>{tab==="Home"&&<><section className="hero"><small>GOOD AFTERNOON</small><h1>What can we bring you?</h1></section><label className="search"><b>⌕</b><input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder="Search products and stores..."/><kbd>⌘ K</kbd></label>
      <section><div className="section-title"><div><h2>Choose a service</h2><p>Everything local, one account</p></div></div><div className="services">{serviceMeta.map((x)=><button disabled={!enabled(x.name)} key={x.name} className={service===x.name?"active":""} onClick={()=>{setService(x.name);setQuery("")}}><i>{x.letter}</i><b>{x.name}</b><small>{enabled(x.name)?x.note:"Paused"}</small></button>)}</div></section>
      <section className="promo"><div><small>GOOCART LIVE</small><h2>{commerce.includes(service)?"Fresh picks,\nright on time.":service==="Bike Taxi"?"Your ride,\nright away.":"Pickup to drop,\nhandled with care."}</h2><p>Live availability and pricing for Jangareddigudem.</p><button onClick={()=>document.querySelector(".discover")?.scrollIntoView()}>Explore now →</button></div><div className="promo-mark">g</div></section>
      {commerce.includes(service)?<ProductGrid products={products.filter((x)=>`${x.name} ${x.vendor}`.toLowerCase().includes(query.toLowerCase()))} add={add} cart={cart}/>:<Booking service={service} state={state} act={act} busy={busy}/>}</>}
      {tab==="Search"&&<Search products={state.products} query={query} setQuery={setQuery} add={add} cart={cart}/>} 
      {tab==="Activity"&&<Activity orders={activeOrders}/>} 
      {tab==="Cart"&&<Cart items={cartItems} total={cartTotal} update={updateQty} checkout={checkout} busy={busy}/>} 
      {tab==="Account"&&<Account orders={activeOrders} user={state.actor}/>} 
    </main><nav className="bottom">{nav.customer.map((x)=><button key={x} className={tab===x?"active":""} onClick={()=>setTab(x)}><i>{({Home:"⌂",Search:"⌕",Activity:"↻",Cart:"▱",Account:"○"} as Record<string,string>)[x]}</i>{x}{x==="Cart"&&cartItems.length>0&&<b>{cartItems.reduce((s,x)=>s+x.qty,0)}</b>}</button>)}</nav></div>;
}

function ProductGrid({products,add,cart}:{products:Product[];add:(x:Product)=>void;cart:Record<string,number>}){return <section className="discover"><div className="section-title"><div><h2>Available near you</h2><p>Live inventory from verified local stores</p></div><span>{products.length} items</span></div><div className="product-grid">{products.map((p,i)=><article className="product-card" key={p.id}><div className={`photo p${i%3}`}><b>{p.name[0]}</b><span>{p.eta}</span></div><div className="product-copy"><small>{p.vendor}</small><h3>{p.name}</h3><p>{p.description}</p><div><span><b>{money(p.price)}</b><small>★ {p.rating}</small></span><button disabled={!p.stock} onClick={()=>add(p)}>{cart[p.id]?`${cart[p.id]} added` : p.stock?"Add +":"Sold out"}</button></div></div></article>)}</div></section>}
function Search({products,query,setQuery,add,cart}:{products:Product[];query:string;setQuery:(x:string)=>void;add:(x:Product)=>void;cart:Record<string,number>}){const found=products.filter((x)=>`${x.name} ${x.vendor} ${x.service}`.toLowerCase().includes(query.toLowerCase()));return <section className="page-section"><div className="page-head"><small>ALL SERVICES</small><h1>Search Goocart</h1><p>Find products and local stores across every service.</p></div><label className="search page-search"><b>⌕</b><input value={query} onChange={(e)=>setQuery(e.target.value)} placeholder="Try biryani, milk or tomatoes..."/></label><ProductGrid products={found} add={add} cart={cart}/></section>}
function Activity({orders}:{orders:Order[]}){return <section className="page-section"><div className="page-head"><small>LIVE HISTORY</small><h1>Your activity</h1><p>Commerce orders, rides and parcels in one timeline.</p></div><div className="activity-list">{orders.length?orders.map((o)=>{const code=detail(o,"verificationCode","");return <article key={o.id}><div className="order-service">{o.service[0]}</div><div><small>{o.reference}</small><h3>{o.vendor}</h3><p>{o.service} • {new Date(o.created_at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}</p>{code&&!terminalStatuses.includes(o.status)&&<p className="delivery-pin">Delivery PIN <b>{code}</b> <small>Share only at pickup/start or delivery</small></p>}</div><Status value={o.status}/><strong>{money(o.total)}</strong></article>}):<Empty title="Nothing here yet" copy="Your orders, rides and parcels will appear here."/>}</div></section>}
function Cart({items,total,update,checkout,busy}:{items:{product:Product;qty:number}[];total:number;update:(id:string,n:number)=>void;checkout:()=>void;busy:boolean}){return <section className="page-section"><div className="page-head"><small>ONE STORE CHECKOUT</small><h1>Your cart</h1><p>{items[0]?.product.vendor||"Add something delicious or useful."}</p></div>{items.length?<div className="checkout-layout"><div className="cart-items">{items.map(({product,qty})=><article key={product.id}><i>{product.name[0]}</i><span><h3>{product.name}</h3><p>{money(product.price)} each</p></span><div className="qty"><button onClick={()=>update(product.id,-1)}>−</button><b>{qty}</b><button onClick={()=>update(product.id,1)}>+</button></div><strong>{money(product.price*qty)}</strong></article>)}</div><aside className="bill"><h2>Bill details</h2><p><span>Item subtotal</span><b>{money(total)}</b></p><p><span>Delivery fee</span><b>₹29</b></p><p><span>Platform fee</span><b>₹5</b></p><hr/><p className="grand"><span>To pay</span><b>{money(total+34)}</b></p><div className="address-row"><small>DELIVER TO</small><b>Home • Jangareddigudem</b></div><button className="primary" disabled={busy} onClick={checkout}>{busy?"Placing order...":`Place order • ${money(total+34)}`}</button></aside></div>:<Empty title="Your cart is empty" copy="Browse a service and add items to start an order."/>}</section>}
function Account({orders,user}:{orders:Order[];user:PlatformUser}){return <section className="page-section account-page"><div className="account-hero"><div>{user.name.slice(0,2).toUpperCase()}</div><span><small>GOOCART CUSTOMER</small><h1>{user.name}</h1><p>{user.email} • {orders.length} activities</p></span><button className="signout-link" onClick={()=>void logout()}>Sign out</button></div><div className="account-grid">{["Saved Addresses","Payments","Goocart Wallet","Coupons","Ratings & Reviews","Help & Support","Notifications","Language & Legal"].map((x)=><button key={x}><i>{x[0]}</i><span>{x}<small>View and manage</small></span><b>›</b></button>)}</div></section>}
function Booking({service,state,act,busy}:{service:Service;state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [pickup,setPickup]=useState("Home, Jangareddigudem");const [drop,setDrop]=useState("");const [packageType,setPackageType]=useState("Documents");const distance=4.2;const rule=state.pricing.find((x)=>x.service===service);const fare=rule?Math.round(rule.base_fare+rule.per_km*distance+rule.platform_fee):0;return <section className="booking discover"><div className="booking-map"><span>PICKUP</span><b>{pickup}</b><i/><span>DROP</span><b>{drop||"Choose destination"}</b><div className="map-road">g</div></div><div className="booking-form"><small>{service.toUpperCase()}</small><h2>{service==="Bike Taxi"?"Where are you going?":"Send a parcel locally"}</h2><label>Pickup<input value={pickup} onChange={(e)=>setPickup(e.target.value)}/></label><label>Drop<input value={drop} onChange={(e)=>setDrop(e.target.value)} placeholder="Enter destination"/></label>{service==="Parcel"&&<label>Package type<select value={packageType} onChange={(e)=>setPackageType(e.target.value)}><option>Documents</option><option>Food Package</option><option>Clothes</option><option>Small Package</option><option>Medium Package</option></select></label>}<div className="fare"><span><small>ESTIMATED</small><b>4.2 km • 12 min</b></span><strong>{money(fare)}</strong></div><button className="primary" disabled={!drop||busy||!rule} onClick={()=>void act({action:"job.create",service,pickup,drop,packageType,distance})}>{busy?"Booking...":service==="Bike Taxi"?"Book bike":"Book parcel pickup"}</button></div></section>}

function Shell({app,page,setPage,children,state,act,busy}:{app:"vendor"|"partner"|"admin";page:string;setPage:(x:string)=>void;children:React.ReactNode;state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const online=state.settings.partner_online==="true";return <div className="workspace"><aside><Brand/><small>{app==="partner"?"DELIVERY PARTNER":app.toUpperCase()} PORTAL</small><nav>{nav[app].map((x)=><button className={page===x?"active":""} onClick={()=>setPage(x)} key={x}><i>{x[0]}</i>{x}</button>)}</nav><div className="profile"><b>{state.actor.name.slice(0,2).toUpperCase()}</b><span>{state.actor.name}<small>{label(state.actor.role)}</small></span></div></aside><main><header><span><small>JANGAREDDIGUDEM • LIVE</small><h1>{page}</h1></span><div><button className="signout-link" onClick={()=>void logout()}>Sign out</button>{app==="partner"&&<button className={online?"online-toggle on":"online-toggle"} disabled={busy} onClick={()=>void act({action:"partner.toggle",value:!online})}>● {online?"Online":"Offline"}</button>}</div></header>{children}</main></div>}
function Kpis({items}:{items:[string,string,string][]}){return <section className="kpis">{items.map((x)=><article key={x[1]}><small>{x[1]}</small><strong>{x[0]}</strong><em>{x[2]}</em></article>)}</section>}
function OrdersTable({orders,actor,act,busy,showFlow=false}:{orders:Order[];actor:"vendor"|"partner"|"admin";act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean;showFlow?:boolean}){return <div className="ops-table"><div className="ops-row ops-head"><span>REFERENCE</span><span>DETAILS</span><span>STATUS</span><span>VALUE</span><span>ACTION</span></div>{orders.map((o)=><div className="ops-row" key={o.id}><b>{o.reference}</b><span>{actor==="partner"?o.customer:o.vendor}<small>{o.service} • {orderSummary(o)}</small>{showFlow&&<FlowStrip order={o} actor={actor}/>}</span><Status value={o.status}/><strong>{money(o.total)}</strong><OrderAction order={o} actor={actor} act={act} busy={busy}/></div>)}{!orders.length&&<Empty title="No matching work" copy="New activity will appear here automatically."/>}</div>}
function flowFor(order:Order,role:"vendor"|"partner"|"admin"){if(role==="vendor")return ["Placed","Accepted","Preparing","Ready","Handed off"];if(order.service==="Bike Taxi")return ["Accepted","At pickup","Ride started","Completed"];return ["Accepted","At pickup","Picked up","On the way","Delivered"];}
function flowIndex(order:Order,role:"vendor"|"partner"|"admin"){const vendor:Record<string,number>={PLACED:0,VENDOR_ACCEPTED:1,PREPARING:2,READY_FOR_PICKUP:3,DELIVERY_PARTNER_ASSIGNED:4,PICKED_UP:4,ON_THE_WAY:4,DELIVERED:4};const partner:Record<string,number>={READY_FOR_PICKUP:0,REQUESTED:0,CREATED:0,DELIVERY_PARTNER_ASSIGNED:1,DRIVER_ASSIGNED:1,PARTNER_ASSIGNED:1,PICKED_UP:2,RIDE_STARTED:2,ON_THE_WAY:3,DELIVERED:4,COMPLETED:3};return (role==="vendor"?vendor:partner)[order.status]??0;}
function FlowStrip({order,actor}:{order:Order;actor:"vendor"|"partner"|"admin"}){const stages=flowFor(order,actor);const current=flowIndex(order,actor);return <div className="flow-strip" aria-label={`${actor} order flow`}>{stages.map((stage,index)=><span className={index<current?"done":index===current?"current":""} key={stage}><i>{index<current?"✓":index+1}</i>{stage}</span>)}</div>}
function OrderAction({order,actor,act,busy}:{order:Order;actor:"vendor"|"partner"|"admin";act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [verifying,setVerifying]=useState(false);const [code,setCode]=useState("");let actions:{to:string;text:string;verify?:boolean;danger?:boolean}[]=[];if(actor==="vendor")actions=order.status==="PLACED"?[{to:"VENDOR_ACCEPTED",text:"Accept"},{to:"VENDOR_REJECTED",text:"Reject",danger:true}]:order.status==="VENDOR_ACCEPTED"?[{to:"PREPARING",text:"Start preparing"}]:order.status==="PREPARING"?[{to:"READY_FOR_PICKUP",text:"Mark ready"}]:[];if(actor==="partner"){const map:Record<string,{to:string;text:string;verify?:boolean}>={READY_FOR_PICKUP:{to:"DELIVERY_PARTNER_ASSIGNED",text:"Accept delivery"},DELIVERY_PARTNER_ASSIGNED:{to:"PICKED_UP",text:"Confirm pickup"},PICKED_UP:{to:"ON_THE_WAY",text:"Start delivery"},ON_THE_WAY:{to:"DELIVERED",text:"Verify & deliver",verify:true},REQUESTED:{to:"DRIVER_ASSIGNED",text:"Accept ride"},DRIVER_ASSIGNED:{to:"RIDE_STARTED",text:"Verify PIN & start",verify:true},RIDE_STARTED:{to:"COMPLETED",text:"Complete ride"},CREATED:{to:"PARTNER_ASSIGNED",text:"Accept parcel"},PARTNER_ASSIGNED:{to:"PICKED_UP",text:"Confirm pickup"},IN_TRANSIT:{to:"DELIVERED",text:"Verify & deliver",verify:true}};if(map[order.status])actions=[map[order.status]];}if(actor==="admin"&&!terminalStatuses.includes(order.status))actions=[{to:"CANCELLED_BY_ADMIN",text:"Cancel",danger:true}];const run=async(to:string,verify?:boolean)=>{if(verify&&!verifying){setVerifying(true);return;}const ok=await act({action:"order.transition",id:order.id,to,code});if(ok){setVerifying(false);setCode("");}};return <div className="row-actions">{actions.map((x)=><div className="action-stack" key={x.to}>{verifying&&x.verify?<form onSubmit={(e)=>{e.preventDefault();void run(x.to,true)}} className="verify-form"><input required pattern="[0-9]{4}" inputMode="numeric" maxLength={4} value={code} onChange={(e)=>setCode(e.target.value.replace(/\D/g,""))} aria-label="Customer verification PIN" placeholder="4-digit PIN"/><button disabled={busy||code.length!==4}>Confirm</button><button type="button" className="quiet" onClick={()=>setVerifying(false)}>×</button></form>:<button className={x.danger?"danger":""} disabled={busy} onClick={()=>void run(x.to,x.verify)}>{x.text}</button>}</div>)}</div>}

function Vendor({state,act,busy}:{state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [page,setPage]=useState("Dashboard");const orders=state.orders.filter((x)=>commerce.includes(x.service));const products=state.products;const delivered=orders.filter((x)=>x.status==="DELIVERED");const revenue=delivered.reduce((s,x)=>s+x.total,0);const open=state.settings.vendor_open!=="false";const live=orders.filter((x)=>!terminalStatuses.includes(x.status));return <Shell app="vendor" page={page} setPage={setPage} state={state} act={act} busy={busy}>{page==="Dashboard"&&<><div className="overview"><span><small>STORE OPERATIONS</small><h2>Run every order from one place.</h2></span><button className={open?"store-open":"store-closed"} onClick={()=>void act({action:"vendor.toggle",value:!open})}>● Store {open?"open":"closed"}</button></div><div className="journey-banner"><span><i>1</i>Receive</span><b>→</b><span><i>2</i>Accept</span><b>→</b><span><i>3</i>Prepare</span><b>→</b><span><i>4</i>Hand off</span><b>→</b><span><i>5</i>Get paid</span></div><Kpis items={[[String(live.length),"Live orders","Needs action"],[money(revenue),"Completed revenue","All time"],[String(orders.filter((x)=>x.status==="PREPARING").length),"Preparing now","Kitchen queue"],[String(products.filter((x)=>x.stock<15).length),"Low stock","Needs attention"]]}/><section className="panel"><div><span><h2>Orders needing attention</h2><small>Updates are shared with customer and delivery partner apps</small></span><button onClick={()=>setPage("Orders")}>View all</button></div><OrdersTable orders={live.slice(0,6)} actor="vendor" act={act} busy={busy} showFlow/></section></>}{page==="Orders"&&<VendorOrders orders={orders} act={act} busy={busy}/>} {page==="Products / Menu"&&<Inventory products={products} act={act} busy={busy} mode="menu"/>}{page==="Inventory"&&<Inventory products={products} act={act} busy={busy} mode="stock"/>}{page==="Store"&&<TogglePage title="Store availability" copy="Closing the store removes its products from customer discovery while existing orders remain actionable." value={open} onToggle={()=>void act({action:"vendor.toggle",value:!open})}/>} {page==="Payments"&&<VendorPayments orders={orders}/>} {page==="Offers"&&<VendorOffers offers={state.offers} act={act} busy={busy}/>} {page==="Profile"&&<ProfilePage accountRole={label(state.actor.role)} name={state.actor.name} details={[state.actor.email,label(state.actor.status),`${products.length} live products`,"Jangareddigudem service area"]}/>}</Shell>}
function VendorOrders({orders,act,busy}:{orders:Order[];act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [filter,setFilter]=useState("Active");const filters=["Active","New","Preparing","Ready","Completed","All"];const visible=orders.filter((order)=>filter==="All"||filter==="Active"&&!terminalStatuses.includes(order.status)||filter==="New"&&order.status==="PLACED"||filter==="Preparing"&&["VENDOR_ACCEPTED","PREPARING"].includes(order.status)||filter==="Ready"&&order.status==="READY_FOR_PICKUP"||filter==="Completed"&&terminalStatuses.includes(order.status));return <WorkspacePage eyebrow="ORDER ENGINE" title="Manage orders" copy="Accept, prepare and hand off orders in the sequence shown."><div className="filter-bar">{filters.map((item)=><button className={filter===item?"active":""} key={item} onClick={()=>setFilter(item)}>{item}<b>{item==="All"?orders.length:orders.filter((o)=>item==="Active"?!terminalStatuses.includes(o.status):item==="New"?o.status==="PLACED":item==="Preparing"?["VENDOR_ACCEPTED","PREPARING"].includes(o.status):item==="Ready"?o.status==="READY_FOR_PICKUP":terminalStatuses.includes(o.status)).length}</b></button>)}</div><OrdersTable orders={visible} actor="vendor" act={act} busy={busy} showFlow/></WorkspacePage>}
function Inventory({products,act,busy,mode}:{products:Product[];act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean;mode:"menu"|"stock"}){const visible=mode==="stock"?[...products].sort((a,b)=>a.stock-b.stock):products;return <WorkspacePage eyebrow={mode==="menu"?"LIVE CATALOG":"STOCK CONTROL"} title={mode==="menu"?"Products & menu":"Inventory"} copy={mode==="menu"?"Create products and keep customer-facing information current.":"Replenish low-stock products before they sell out."}>{mode==="menu"&&<ProductForm act={act} busy={busy}/>}<div className="inventory-summary"><span><b>{products.length}</b> products</span><span><b>{products.filter((p)=>p.stock<15).length}</b> low stock</span><span><b>{products.filter((p)=>p.stock===0).length}</b> sold out</span></div><div className="inventory-list">{visible.map((p)=><article key={p.id}><i>{p.name[0]}</i><span><small>{p.service}</small><h3>{p.name}</h3><p>{money(p.price)} • {p.description}</p></span><b className={p.stock<15?"low-stock":""}>{p.stock} in stock</b><div className="qty"><button aria-label={`Remove one ${p.name}`} disabled={busy||p.stock===0} onClick={()=>void act({action:"stock.adjust",id:p.id,amount:-1})}>−</button><button aria-label={`Add five ${p.name}`} disabled={busy} onClick={()=>void act({action:"stock.adjust",id:p.id,amount:5})}>+5</button><button aria-label={`Add twenty ${p.name}`} disabled={busy} onClick={()=>void act({action:"stock.adjust",id:p.id,amount:20})}>+20</button></div></article>)}{!products.length&&<Empty title="No products yet" copy="Create your first product using the form above."/>}</div></WorkspacePage>}
function ProductForm({act,busy}:{act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [open,setOpen]=useState(false);const [form,setForm]=useState({service:"Food",name:"",description:"",price:"",stock:"",eta:"30–45 min"});const submit=async(e:React.FormEvent)=>{e.preventDefault();const ok=await act({action:"product.create",...form,price:Number(form.price),stock:Number(form.stock)});if(ok){setForm({...form,name:"",description:"",price:"",stock:""});setOpen(false);}};return <div className="product-create"><button className="primary" onClick={()=>setOpen(!open)}>{open?"Close form":"+ Create product"}</button>{open&&<form onSubmit={(e)=>void submit(e)}><label>Service<select value={form.service} onChange={(e)=>setForm({...form,service:e.target.value})}>{commerce.map((x)=><option key={x}>{x}</option>)}</select></label><label>Name<input required minLength={2} value={form.name} onChange={(e)=>setForm({...form,name:e.target.value})}/></label><label>Description<input required minLength={3} value={form.description} onChange={(e)=>setForm({...form,description:e.target.value})}/></label><label>Price<input required min="1" type="number" value={form.price} onChange={(e)=>setForm({...form,price:e.target.value})}/></label><label>Opening stock<input required min="0" type="number" value={form.stock} onChange={(e)=>setForm({...form,stock:e.target.value})}/></label><button className="primary" disabled={busy}>Save product</button></form>}</div>}

function VendorOffers({offers,act,busy}:{offers:Offer[];act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [form,setForm]=useState({title:"",code:"",discountPercent:"10",minOrder:"299"});const submit=async(e:React.FormEvent)=>{e.preventDefault();const ok=await act({action:"offer.create",...form,discountPercent:Number(form.discountPercent),minOrder:Number(form.minOrder)});if(ok)setForm({title:"",code:"",discountPercent:"10",minOrder:"299"});};return <WorkspacePage eyebrow="PROMOTIONS" title="Offers" copy="Create store-funded offers and pause them at any time."><form className="offer-form" onSubmit={(e)=>void submit(e)}><label>Offer title<input required minLength={3} placeholder="Weekend saver" value={form.title} onChange={(e)=>setForm({...form,title:e.target.value})}/></label><label>Customer code<input required minLength={3} maxLength={16} placeholder="SAVE10" value={form.code} onChange={(e)=>setForm({...form,code:e.target.value.toUpperCase().replace(/[^A-Z0-9]/g,"")})}/></label><label>Discount %<input required min="1" max="60" type="number" value={form.discountPercent} onChange={(e)=>setForm({...form,discountPercent:e.target.value})}/></label><label>Minimum order<input required min="0" type="number" value={form.minOrder} onChange={(e)=>setForm({...form,minOrder:e.target.value})}/></label><button className="primary" disabled={busy}>Publish offer</button></form><div className="offer-list">{offers.map((offer)=><article key={offer.id}><div><small>{offer.active?"LIVE OFFER":"PAUSED"}</small><h3>{offer.title}</h3><p><b>{offer.code}</b> • {offer.discount_percent}% off above {money(offer.min_order)}</p></div><button className={offer.active?"toggle on":"toggle"} aria-label={`${offer.active?"Pause":"Activate"} ${offer.title}`} onClick={()=>void act({action:"offer.toggle",id:offer.id,active:!offer.active})}><i/></button></article>)}{!offers.length&&<Empty title="No offers yet" copy="Publish your first discount using the form above."/>}</div></WorkspacePage>}
function VendorPayments({orders}:{orders:Order[]}){const completed=orders.filter((o)=>o.status==="DELIVERED");const gross=completed.reduce((sum,o)=>sum+o.total,0);const commission=gross*.18;const net=gross-commission;return <WorkspacePage eyebrow="SETTLEMENTS" title="Payments" copy="A transparent view of completed-order earnings and platform commission."><div className="settlement-card"><div><small>NEXT SETTLEMENT</small><strong>{money(net)}</strong><span>Expected Friday • bank account ending 4821</span></div><button>Download statement</button></div><Kpis items={[[money(gross),"Gross sales","Delivered orders"],[money(commission),"Platform commission","18%"],[money(net),"Net payable","Next cycle"],[String(completed.length),"Paid orders","Included"]]}/><section className="panel"><div><span><h2>Settlement ledger</h2><small>Net amount after 18% commission</small></span></div><div className="payment-ledger">{completed.map((order)=><article key={order.id}><span><b>{order.reference}</b><small>{new Date(order.updated_at).toLocaleDateString("en-IN",{dateStyle:"medium"})}</small></span><span>{money(order.total)}<small>Gross</small></span><strong>{money(order.total*.82)}<small>Net payable</small></strong></article>)}{!completed.length&&<Empty title="No settlements yet" copy="Completed deliveries will appear in this ledger."/>}</div></section></WorkspacePage>}

function Partner({state,act,busy}:{state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [page,setPage]=useState("Home");const online=state.settings.partner_online==="true";const available=state.orders.filter((x)=>["READY_FOR_PICKUP","REQUESTED","CREATED"].includes(x.status));const current=state.orders.filter((x)=>x.partner_id===state.actor.id&&!terminalStatuses.includes(x.status));const completed=state.orders.filter((x)=>x.partner_id===state.actor.id&&["DELIVERED","COMPLETED"].includes(x.status));const earnings=completed.reduce((s,x)=>s+Math.max(35,x.total*.12),0);return <Shell app="partner" page={page} setPage={setPage} state={state} act={act} busy={busy}>{page==="Home"&&<><div className="overview"><span><small>{online?"YOU ARE ONLINE":"YOU ARE OFFLINE"}</small><h2>Ready when you are, {state.actor.name.split(" ")[0]}.</h2></span>{current.length>0&&<button className="current-task-link" onClick={()=>setPage("Current Task")}>Continue current task →</button>}</div><div className="journey-banner partner-journey"><span><i>1</i>Go online</span><b>→</b><span><i>2</i>Accept</span><b>→</b><span><i>3</i>Navigate</span><b>→</b><span><i>4</i>Verify</span><b>→</b><span><i>5</i>Earn</span></div><Kpis items={[[money(earnings),"Total earnings","Live"],[String(completed.length),"Completed trips","All time"],[String(available.length),"Nearby requests",online?"Available":"Go online"],["4.9","Partner rating","Excellent"]]}/>{current.length?<section className="panel"><div><span><h2>Current task</h2><small>Complete this before accepting another request</small></span></div><PartnerTask order={current[0]} act={act} busy={busy}/></section>:<section className="panel"><div><span><h2>Nearby requests</h2><small>{online?"Matched for your vehicle and service area":"Go online to receive requests"}</small></span></div>{online?<RequestCards orders={available.slice(0,4)} act={act} busy={busy}/>:<Empty title="You are offline" copy="Switch online to see eligible delivery, ride and parcel work."/>}</section>}</>}{page==="Requests"&&<WorkspacePage eyebrow="MATCHING ENGINE" title="Available requests" copy="Review route, distance and earnings before accepting.">{!online?<Empty title="Go online first" copy="Requests are only shown while you are available."/>:current.length?<Empty title="Finish your current task" copy="New requests unlock automatically after completion."/>:<RequestCards orders={available} act={act} busy={busy}/>}</WorkspacePage>}{page==="Current Task"&&<WorkspacePage eyebrow="ACTIVE WORK" title="Current task" copy="Follow each step and verify the customer PIN when requested.">{current.length?<PartnerTask order={current[0]} act={act} busy={busy}/>:<Empty title="No active task" copy="Go online and accept a nearby request to begin."/>}</WorkspacePage>}{page==="Trips"&&<WorkspacePage eyebrow="HISTORY" title="Completed work" copy="Your completed deliveries, rides and parcels."><OrdersTable orders={completed} actor="partner" act={act} busy={busy}/></WorkspacePage>}{page==="Earnings"&&<PartnerEarnings orders={completed} earnings={earnings}/>} {page==="Support"&&<PartnerSupport/>} {page==="Profile"&&<ProfilePage accountRole="Delivery partner" name={state.actor.name} details={[state.actor.email,"Bike • AP 37 BK 4821","All services eligible","Documents verified",online?"Online":"Offline"]}/>}</Shell>}
function RequestCards({orders,act,busy}:{orders:Order[];act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){return <div className="request-grid">{orders.map((order)=><article className="request-card" key={order.id}><header><i>{order.service[0]}</i><span><small>{order.service.toUpperCase()}</small><h3>{order.vendor}</h3></span><strong>{money(Math.max(35,order.total*.12))}<small>estimated</small></strong></header><div className="route-points"><span><i/><small>PICKUP</small><b>{commerce.includes(order.service)?order.vendor:detail(order,"pickup")}</b></span><span><i/><small>DROP</small><b>{commerce.includes(order.service)?detail(order,"address","Customer address"):detail(order,"drop")}</b></span></div><div className="request-meta"><span><b>{detail(order,"distance","4.2")} km</b><small>Distance</small></span><span><b>12–18 min</b><small>Estimated</small></span><span><b>{order.customer}</b><small>Customer</small></span></div><OrderAction order={order} actor="partner" act={act} busy={busy}/></article>)}{!orders.length&&<Empty title="No nearby requests" copy="Stay online—new matched work will appear automatically."/>}</div>}
function PartnerTask({order,act,busy}:{order:Order;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){return <article className="partner-task"><div className="task-map"><div className="map-grid"/><span className="pickup-dot">P</span><span className="drop-dot">D</span><b>g</b><small>Live route • {detail(order,"distance","4.2")} km</small></div><div className="task-details"><div className="task-title"><span><small>{order.reference}</small><h2>{order.service}</h2></span><Status value={order.status}/></div><FlowStrip order={order} actor="partner"/><div className="route-points"><span><i/><small>PICKUP</small><b>{commerce.includes(order.service)?order.vendor:detail(order,"pickup")}</b></span><span><i/><small>DROP</small><b>{commerce.includes(order.service)?detail(order,"address","Customer address"):detail(order,"drop")}</b></span></div><div className="customer-contact"><i>{order.customer[0]}</i><span><b>{order.customer}</b><small>{orderSummary(order)}</small></span><a href="tel:+9118004662278">Call</a></div><div className="task-actions"><button className="secondary">Open navigation</button><OrderAction order={order} actor="partner" act={act} busy={busy}/></div><p className="safety-note">Only request the customer’s PIN when the app asks for verification. Never ask over a phone call.</p></div></article>}
function PartnerEarnings({orders,earnings}:{orders:Order[];earnings:number}){return <WorkspacePage eyebrow="WALLET & PAYOUTS" title="Earnings" copy="Every completed task and its payable amount."><div className="settlement-card partner-settlement"><div><small>AVAILABLE BALANCE</small><strong>{money(earnings)}</strong><span>Next automatic payout • Friday</span></div><button>View bank account</button></div><Kpis items={[[money(earnings),"Total earnings","All time"],[money(orders.reduce((s,o)=>s+Math.max(35,o.total*.12),0)),"Next payout","Scheduled"],[String(orders.length),"Completed jobs","Verified"],[orders.length?money(earnings/orders.length):"₹0","Average per job","Calculated"]]}/><div className="payment-ledger partner-ledger">{orders.map((order)=><article key={order.id}><span><b>{order.service} • {order.reference}</b><small>{new Date(order.updated_at).toLocaleString("en-IN",{dateStyle:"medium",timeStyle:"short"})}</small></span><span>{detail(order,"distance","4.2")} km<small>{order.customer}</small></span><strong>{money(Math.max(35,order.total*.12))}<small>Earned</small></strong></article>)}{!orders.length&&<Empty title="No earnings yet" copy="Completed tasks will appear here instantly."/>}</div></WorkspacePage>}
function PartnerSupport(){return <WorkspacePage eyebrow="SAFETY & SUPPORT" title="Partner support" copy="Fast help for active-task issues, safety concerns and account questions."><div className="support-hero"><div><small>24/7 ACTIVE-TASK SUPPORT</small><h2>Need help on the road?</h2><p>Use emergency support only when you or a customer may be at risk.</p></div><a href="tel:+9118004662278">Call partner care</a></div><div className="support-grid">{[["Active task issue","Customer unavailable, wrong address or pickup delay"],["Safety emergency","Accident, harassment or unsafe location"],["Payment question","Missing earning or settlement status"],["Account & documents","Vehicle, identity or availability help"]].map((item)=><button key={item[0]}><i>{item[0][0]}</i><span><b>{item[0]}</b><small>{item[1]}</small></span><strong>›</strong></button>)}</div></WorkspacePage>}

function Admin({state,act,busy}:{state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){const [page,setPage]=useState("Dashboard");const orders=state.orders;const gmv=orders.reduce((s,x)=>s+x.total,0);const active=orders.filter((x)=>!["DELIVERED","COMPLETED","CANCELLED_BY_ADMIN","VENDOR_REJECTED"].includes(x.status));const rides=orders.filter((x)=>x.service==="Bike Taxi");const parcels=orders.filter((x)=>x.service==="Parcel");return <Shell app="admin" page={page} setPage={setPage} state={state} act={act} busy={busy}>{page==="Dashboard"&&<><div className="overview"><span><small>Command center</small><h2>Operations at a glance.</h2></span><b>LIVE D1 DATA</b></div><Kpis items={[[money(gmv),"Total GMV","All services"],[String(orders.length),"Total orders & jobs","Live"],[String(active.length),"Active operations","Now"],[String(state.services.filter((x)=>x.enabled).length),"Enabled services","of 6"]]}/><section className="panel"><div><span><h2>Live operations</h2><small>Customer, vendor and partner activity</small></span></div><OrdersTable orders={active.slice(0,7)} actor="admin" act={act} busy={busy}/></section></>}{["Live Operations","Orders"].includes(page)&&<WorkspacePage eyebrow="REALTIME OPERATIONS" title={page} copy="Monitor status and intervene when necessary."><OrdersTable orders={page==="Orders"?orders:active} actor="admin" act={act} busy={busy}/></WorkspacePage>}{page==="Rides"&&<WorkspacePage eyebrow="RIDE ENGINE" title="Bike taxi" copy="Ride requests, driver assignments and completions."><OrdersTable orders={rides} actor="admin" act={act} busy={busy}/></WorkspacePage>}{page==="Parcels"&&<WorkspacePage eyebrow="PARCEL ENGINE" title="Parcel operations" copy="Pickup, transit and delivery verification."><OrdersTable orders={parcels} actor="admin" act={act} busy={busy}/></WorkspacePage>}{page==="Catalog"&&<AdminCatalog state={state} act={act} busy={busy}/>} {page==="Settings"&&<AdminSettings state={state} act={act}/>} {page==="Finance"&&<StatsPage title="Platform finance" stats={[["Gross merchandise value",money(gmv)],["Platform revenue",money(gmv*.18)],["Vendor payable",money(gmv*.82)]]}/>} {page==="Vendors"&&<Directory title="Verified vendors" rows={Array.from(new Set(state.products.map((x)=>x.vendor))).map((x,i)=>[x,`${state.products.filter((p)=>p.vendor===x).length} products`,i%2?"Open":"Approved"])} />} {page==="Delivery Partners"&&<Directory title="Delivery partners" rows={[["Ravi Kumar","Bike • All services",state.settings.partner_online==="true"?"Online":"Offline"],["Anil K","EV Scooter • Commerce","Offline"],["Suresh B","Bike • Rides & Parcel","Online"]]}/>} {page==="Customers"&&<Directory title="Customers" rows={[["Bhargav Reddy",`${orders.length} activities`,money(gmv)],["Kavya S","4 activities","₹1,840"],["Ramesh K","2 activities","₹760"]]}/>} {page==="Support"&&<Directory title="Support tickets" rows={[["#TKT-1042","Order delayed","Open"],["#TKT-1039","Payment issue","In progress"],["#TKT-1034","Missing item","Resolved"]]}/>} {page==="Reports"&&<StatsPage title="Performance reports" stats={commerce.map((x)=>[x,`${orders.filter((o)=>o.service===x).length} orders`])}/>}</Shell>}
function AdminCatalog({state,act,busy}:{state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>;busy:boolean}){return <WorkspacePage eyebrow="CATALOG & INVENTORY" title="All products" copy="Live price, stock and service availability."><div className="inventory-list">{state.products.map((p)=><article key={p.id}><i>{p.name[0]}</i><span><small>{p.service} • {p.vendor}</small><h3>{p.name}</h3><p>{money(p.price)} • ★ {p.rating}</p></span><b className={p.stock<15?"low-stock":""}>{p.stock} stock</b><div className="qty"><button disabled={busy} onClick={()=>void act({action:"stock.adjust",id:p.id,amount:-1})}>−</button><button disabled={busy} onClick={()=>void act({action:"stock.adjust",id:p.id,amount:5})}>+5</button></div></article>)}</div></WorkspacePage>}
function AdminSettings({state,act}:{state:Snapshot;act:(x:Record<string,unknown>)=>Promise<boolean>}){return <WorkspacePage eyebrow="SERVICE AREA" title="Jangareddigudem" copy="Enable services independently for this operating area."><div className="setting-list">{state.services.map((s)=><article key={s.service}><i>{s.service[0]}</i><span><b>{s.service}</b><small>{s.enabled?"Available to customers":"Temporarily unavailable"}</small></span><button className={s.enabled?"toggle on":"toggle"} onClick={()=>void act({action:"service.toggle",service:s.service,enabled:!s.enabled})}><i/></button></article>)}</div></WorkspacePage>}
function WorkspacePage({eyebrow,title,copy,children}:{eyebrow:string;title:string;copy:string;children:React.ReactNode}){return <section className="workspace-page"><div className="page-head"><small>{eyebrow}</small><h1>{title}</h1><p>{copy}</p></div>{children}</section>}
function TogglePage({title,copy,value,onToggle}:{title:string;copy:string;value:boolean;onToggle:()=>void}){return <WorkspacePage eyebrow="AVAILABILITY" title={title} copy={copy}><div className="big-toggle"><span><b>{value?"Open and accepting orders":"Closed to new orders"}</b><small>Updated for all customer sessions</small></span><button className={value?"toggle on":"toggle"} onClick={onToggle}><i/></button></div></WorkspacePage>}
function StatsPage({title,stats}:{title:string;stats:string[][]}){return <WorkspacePage eyebrow="LIVE SUMMARY" title={title} copy="Calculated from current platform activity."><div className="stat-list">{stats.map((x)=><article key={x[0]}><span>{x[0]}</span><strong>{x[1]}</strong></article>)}</div></WorkspacePage>}
function Directory({title,rows}:{title:string;rows:string[][]}){return <WorkspacePage eyebrow="DIRECTORY" title={title} copy="Operational records available to this admin role."><div className="directory">{rows.map((x)=><article key={x[0]}><i>{x[0][0]}</i><span><b>{x[0]}</b><small>{x[1]}</small></span><Status value={x[2].toUpperCase().replaceAll(" ","_")}/></article>)}</div></WorkspacePage>}
function ProfilePage({accountRole,name,details}:{accountRole:string;name:string;details:string[]}){return <WorkspacePage eyebrow={accountRole.toUpperCase()} title={name} copy="Verified Goocart account."><div className="profile-panel"><i>{name[0]}</i><div>{details.map((x)=><p key={x}>✓ {x}</p>)}</div></div></WorkspacePage>}

export default function Home(){const {state,busy,toast,error,act,retry}=useGoocart();if(error?.code==="AUTH_REQUIRED")return <AuthGate onAuthenticated={()=>void retry()}/>;if(error)return <main className="fatal"><Brand/><h1>Goocart couldn’t start</h1><p>{error.message}</p><button onClick={()=>void retry()}>Try again</button></main>;if(!state)return <main className="loading"><Brand/><div className="loader"/><p>Starting Goocart...</p></main>;const content=state.actor.role==="CUSTOMER"?<Customer state={state} act={act} busy={busy}/>:state.actor.role==="DELIVERY_PARTNER"?<Partner state={state} act={act} busy={busy}/>:["VENDOR_OWNER","VENDOR_MANAGER"].includes(state.actor.role)?<Vendor state={state} act={act} busy={busy}/>:state.actor.role.includes("ADMIN")?<Admin state={state} act={act} busy={busy}/>:<main className="fatal"><Brand/><h1>Workspace unavailable</h1><p>Your account role is not configured for an app.</p><button onClick={()=>void logout()}>Sign out</button></main>;return <div>{busy&&<div className="syncing">Syncing…</div>}{toast&&<div className="toast">{toast}</div>}{content}</div>}
